<script setup lang="ts">
import {cancerLabel} from '../../../packages/engine/src/cancer';
import {periodAccounts} from '../../../packages/engine/src/time-block';
import {wellbeingReasons,nextPlanningYear} from '../../../packages/engine/src/adult-life';
import {playbackStage,automaticChoice} from '../../../packages/engine/src/playback';
import {immersive} from './presentation';
import CareerSources from './CareerSources.vue';
import {capBand,capResult} from '../../../packages/engine/src/progression';
import Belongings from './Belongings.vue';
import FinanceSummary from './FinanceSummary.vue';
import {bagWeight,chapterKey} from '../../../packages/engine/src/chapters';
import {discardItem} from '../../../packages/engine/src';
import HistoryRecords from './HistoryRecords.vue';
import StudentRecords from './StudentRecords.vue';
import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue';
import {advance,age,chooseFocus,continueAs,createGame,decide,focuses,nextYear,options,player,successors,visibleJournal,nameChild,educationView,characterStatus,sanity,personality,personalityAxes,dismissAdmission,setJuniorFocus,subjectProficiency,subjectScores,juniorSubjects,setSpecialty,setMusicMajor,instruments,setSport,sports,type JuniorSubject,type World,type Language,type Text,type Focus} from '../../../packages/engine/src';
import {deserialize,serialize} from '../../../packages/engine/src/save';
import {attrs,skills,jobs,locations,provenance} from '../../../packages/world-data/src';
import {loadGame,saveGame} from './storage';
import FamilyOverview from './FamilyOverview.vue';
import NamingPanel from './NamingPanel.vue';
import {schools} from '../../../packages/world-data/src/schools';
import {schoolDirectory} from '../../../packages/world-data/src/school-directory';
import MusicMajor from './MusicMajor.vue';
import SportMajor from './SportMajor.vue';
const lang=ref<Language>('zh'),state=ref<World|null>(null),saved=ref<World|null>(null),ready=ref(false),panel=ref('story'),seed=ref(crypto.randomUUID()),birth=ref(2008),notice=ref(''),setup=ref(false),busy=ref(false),saveStatus=ref(''),command=ref('');
const text=(v:Text)=>panel.value==='sources'?v[lang.value]:immersive(v[lang.value]),l=(zh:string,en:string)=>panel.value==='sources'?(lang.value==='zh'?zh:en):immersive(lang.value==='zh'?zh:en);
const p=computed(()=>state.value?player(state.value):null),years=computed(()=>state.value?age(state.value):0);
const autoGraduate=ref(true);
const theme=ref(localStorage.getItem('nyr-theme')??'light'),autoStage=ref('off');
const activeStage=computed(()=>state.value?playbackStage(state.value):'work');
const stageTitle=computed(()=>{const names={kindergarten:['幼稚園','Kindergarten'],primary:['國小','Primary school'],junior:['國中','Junior high'],senior:['高中','Senior high'],vocational:['高職','Vocational school'],juniorCollege:['五專','Junior college'],university:['大學','University'],master:['研究所','Graduate school'],work:['工作','Work'],retired:['退休','Retirement']};const name=names[activeStage.value];return l(name[0],name[1]);});
const autoPauseMessage=computed(()=>{const s=state.value;if(!s||autoStage.value!==activeStage.value)return '';if(s.phase==='naming')return l('自動選擇暫停中：請先幫孩子取名字。','Autoplay is waiting for you to name your child.');if(s.phase==='event'&&(s.current?.kind==='personality'||s.current?.data?.startsWith('profile:')||s.current?.data?.startsWith('type-story:')))return l('自動選擇暫停中：請親自完成這段問答與故事，之後會繼續。','Autoplay is waiting for your answers to this chapter’s questions and story.');return '';});
function toggleAuto(){autoStage.value=autoStage.value===activeStage.value?'off':activeStage.value;}
const capDisplay=computed(()=>!!state.value?.resolution?.checks&&(state.value.current?.kind==='enrollment'&&state.value.current?.data==='senior'||state.value.current?.kind==='schoolstory'&&['route','vocational-department','college-department'].includes(state.value.current?.data??'')));
watch(theme,v=>{document.documentElement.dataset.theme=v;localStorage.setItem('nyr-theme',v);},{immediate:true});
let autoTimer:ReturnType<typeof setTimeout>|undefined;
watch([autoStage,()=>state.value,busy],()=>{clearTimeout(autoTimer);const s=state.value;if(!s||autoStage.value==='off'||busy.value)return;const level=activeStage.value;if(autoStage.value!==level)return;if(s.phase==='naming'||s.phase==='dead'||s.phase==='event'&&(s.current?.kind==='personality'||s.current?.data?.startsWith('profile:')||s.current?.data?.startsWith('type-story:')))return;autoTimer=setTimeout(()=>{if(state.value?.admissionNotice){update(dismissAdmission);return;}if(state.value?.phase==='focus'){const choices=focuses(state.value);const id=automaticChoice(state.value,choices,autoGraduate.value);if(id)choose(id);}else if(state.value?.phase==='event'){const choices=options(state.value).filter(o=>!o.disabled);if(choices.length){const id=automaticChoice(state.value,choices,autoGraduate.value);if(id)choose(id);}}else move();},800);});
onUnmounted(()=>clearTimeout(autoTimer));
const namingError=ref('');
const currentSchool=computed(()=>schools.find(n=>n.id===study.value?.enrollment?.schoolId));
const study=computed(()=>state.value&&p.value?educationView(state.value,p.value):null);
watch(activeStage,()=>{autoStage.value='off';});
function confirmChildName(value:string,parentId?:string){if(!state.value)return;try{const next=nameChild(state.value,value,parentId);state.value=next;namingError.value='';persist();}catch{namingError.value=l('請輸入 1–20 字的名字（不含姓氏），可用文字、空白或連字號。','Enter a 1–20 character given name, without surname. Use letters, spaces or hyphens.');}}

const journal=computed(()=>state.value?visibleJournal(state.value).filter(j=>j.personId===state.value!.playerId&&inPeriod(j.date)):[]);
const life=computed(()=>state.value?.journal.filter(j=>j.personId===state.value!.playerId)??[]);
const period=computed(()=>state.value?periodAccounts(state.value):null);
const inPeriod=(date:string)=>!!period.value&&Number(date.slice(0,4))>=period.value.from&&Number(date.slice(0,4))<=period.value.to;
const report=computed(()=>state.value?.reports.filter(r=>r.personId===p.value?.id).at(-1));
const location=computed(()=>locations.find(v=>v.id===state.value?.locationId));
const phaseLabel=computed(()=>l(({story:'生活進行中',focus:'寫下年度希望',event:'輪到你決定',resolved:'事情的結果',review:'年度回顧',dead:'人生終章',naming:'為孩子取名'} as const)[state.value?.phase??'story'],({story:'Life unfolds',focus:'Your resolution',event:'Your decision',resolved:'The outcome',review:'Year in review',dead:'Life summary',naming:'Name your child'} as const)[state.value?.phase??'story']));
const fortune=computed(()=>report.value&&state.value?.phase==='review'?text(report.value.fortune):l('本年記事','This year'));
let saves=Promise.resolve();
function persist(){if(!state.value)return;const snapshot=JSON.parse(serialize(state.value)) as World;saveStatus.value=l('儲存中…','Saving…');saves=saves.catch(()=>{}).then(()=>saveGame(snapshot)).then(()=>{saved.value=snapshot;saveStatus.value=l('已儲存在此裝置','Saved on this device');}).catch(()=>{saveStatus.value=l('儲存失敗，請匯出備份','Save failed; please export a backup');});}
function update(fn:(s:World)=>World){if(!state.value||busy.value)return;try{state.value=fn(state.value);notice.value='';persist();}catch(e){notice.value=l('這個操作目前無法進行。','This action is unavailable.');console.error(e);}}
function start(){try{state.value=createGame(seed.value,birth.value);setup.value=false;panel.value='story';persist();}catch{notice.value=l('請填入 1980–2026 的出生年及有效種子。','Enter a birth year from 1980–2026 and a valid seed.');}}
function move(){update(s=>s.phase==='review'?nextYear(s):advance(s));}
function skipNarration(){update(s=>{let next=advance(s),steps=0;while(next.phase==='story'&&steps++<40)next=advance(next);return next;});}
function choose(id:string){if(!state.value)return;const prev=state.value;update(s=>s.phase==='focus'?chooseFocus(s,id as Focus):decide(s,id));if(state.value!==prev&&state.value?.rng!==prev.rng&&(state.value?.resolution?.check||state.value?.resolution?.checks)){busy.value=true;setTimeout(()=>{busy.value=false;},550);}}
function resume(){if(saved.value){state.value=deserialize(serialize(saved.value));panel.value='story';notice.value='';}}
function exportSave(){if(!state.value)return;const blob=new Blob([serialize(state.value)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`new-year-${state.value.year}-${state.value.playerId}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function importSave(e:Event){const el=e.target as HTMLInputElement,file=el.files?.[0];try{if(!file)return;if(file.size>12_000_000)throw Error('too large');const next=deserialize(await file.text());state.value=next;panel.value='story';persist();notice.value=l('已讀取備份。','Backup loaded.');}catch{notice.value=l('無法讀取：存檔損壞、版本不相容或資料超出限制；目前進度未更動。','Cannot load: damaged, incompatible or oversized save. Your current progress was not changed.');}finally{el.value='';}}
function freeAction(){const map:Record<string,Focus>={'讀書':'study','學科':'study',study:'study','音樂':'talent',music:'talent','健康':'health',health:'health','工作':'career',work:'career','平衡':'balanced',balance:'balanced'};const f=map[command.value.trim().toLowerCase()];if(state.value?.phase==='focus'&&f&&focuses(state.value).some(o=>o.id===f)){choose(f);command.value='';}else notice.value=l('試玩版支援在年度目標輸入：讀書、音樂、健康、工作、平衡；其他行動尚未開放。','During resolution selection, try study, music, health, work or balance. Other free-text actions are not supported yet.');}
const ageText=computed(()=>{if(!state.value||!p.value)return '';if(years.value===0){const m=Number(state.value.date.slice(5,7))-1;return m===0?l(`出生 ${Number(state.value.date.slice(8))} 天`,`Day ${Number(state.value.date.slice(8))} of life`):l(`${m} 個月`,`${m} months`);}return l(`${years.value} 歲`,`${years.value} years old`);});
function trapFocus(e:KeyboardEvent){if(e.key==='Escape'){setup.value=false;return;}if(e.key!=='Tab')return;const nodes=Array.from(document.querySelectorAll<HTMLElement>('.setup-dialog button,.setup-dialog input'));const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}
let previousFocus:HTMLElement|null=null;
watch(setup,async open=>{if(open){seed.value=crypto.randomUUID();previousFocus=document.activeElement as HTMLElement;await nextTick();document.getElementById('birth-year')?.focus();}else previousFocus?.focus();});
watch(lang,()=>{document.documentElement.lang=lang.value==='zh'?'zh-Hant':'en';});
watch(()=>state.value?.journal.length,async()=>{await nextTick();const el=document.getElementById('year-journal');if(el)el.scrollTop=el.scrollHeight;});
watch(()=>state.value?.admissionNotice?.id,async()=>{await nextTick();document.getElementById('admission-confirm')?.focus();});
watch(()=>state.value?.pendingChildId,()=>{namingError.value='';});
onMounted(async()=>{try{saved.value=await loadGame();}catch{notice.value=l('本機存檔無法讀取；可匯入備份或建立新人生。','Local save could not be read. Import a backup or start a new life.');}finally{ready.value=true;}});
</script>

<template>
 <div class="app-shell"><div v-if="state?.admissionNotice" class="admission-overlay"><section role="dialog" aria-modal="true" aria-labelledby="admission-title" class="admission-dialog" @keydown.tab.prevent="($event.currentTarget as HTMLElement).querySelector('button')?.focus()" @keydown.esc="update(dismissAdmission)"><p class="eyebrow">{{l('新的一段旅程','A NEW CHAPTER')}}</p><h2 id="admission-title">{{text(state.admissionNotice.title)}}</h2><p>{{text(state.admissionNotice.detail)}}</p><button id="admission-confirm" autofocus @click="update(dismissAdmission)">{{l('確認，繼續','Continue')}}</button></section></div>
  <header class="topbar"><a href="#" class="brand" @click.prevent="panel='story'"><span class="brand-mark">年</span><span>新年新希望<small>NEW YEAR RESOLUTION</small></span></a><div class="top-actions"><button class="text-button" @click="theme=theme==='dark'?'light':'dark'">{{theme==='dark'?'☀ 淺色':'☾ 深色'}}</button><button v-if="state" type="button" class="text-button auto-play" :aria-pressed="autoStage===activeStage" :disabled="state.phase==='dead'" @click="toggleAuto">{{autoStage===activeStage?l('❚❚ '+stageTitle+'階段自動選擇（暫停）','❚❚ Pause '+stageTitle+' autoplay'):l('▶ '+stageTitle+'階段自動選擇','▶ '+stageTitle+' autoplay')}}</button><label v-if="state" class="small-note"><input type="checkbox" v-model="autoGraduate">{{l('自動報考研究所','Apply to graduate school in autoplay')}}</label><span class="version">v0.7 · {{l('原型試玩','PLAYABLE PROTOTYPE')}}</span><button class="text-button" @click="lang=lang==='zh'?'en':'zh'" :aria-label="l('切換英文','Switch to Chinese')">{{lang==='zh'?'EN':'繁中'}}</button><button class="text-button" @click="panel=panel==='sources'?'story':'sources'">{{l('關於這個版本','About this version')}}</button></div></header>
  <p v-if="autoPauseMessage" class="notice auto-pause-message" role="status">{{autoPauseMessage}}</p>
  <div v-if="notice" class="notice" role="alert">{{notice}}<button @click="notice=''" :aria-label="l('關閉','Dismiss')">×</button></div>
  <template v-if="!state">
   <main class="landing">
    <div class="landing-copy"><p class="eyebrow">TAIWAN LIFE · TEXT RPG</p><h1 v-if="lang==='zh'">每一年，<br>都有新的<span>可能。</span></h1><h1 v-else>Every year,<br>a new <span>possibility.</span></h1><p class="lead">{{l('在台灣出生，走過自己的人生。\n一些事由你選擇，一些事由生活決定。','Be born in Taiwan. Live your own story.\nSome things are your choice. Others belong to life.')}}</p><div class="landing-buttons"><button class="primary" @click="setup=true" :disabled="!ready">{{l('開始一段人生','Begin a life')}} <span>↗</span></button><button v-if="saved" @click="resume">{{l('繼續上次的人生','Continue your life')}} →</button></div><label class="import-link">{{l('或匯入存檔','Or import a save')}}<input type="file" accept="application/json,.json" @change="importSave"></label><p class="small-note">{{l('繁體中文 / English · 本機存檔 · 無需登入','Traditional Chinese / English · Local saves · No sign-in')}}</p></div>
    <div class="landing-art" aria-hidden="true"><div class="sun"></div><div class="mountain back"></div><div class="mountain front"></div><div class="town"><i></i><i></i><i></i><i></i><i></i><i></i></div><div class="art-caption">日子慢慢過，故事慢慢長。<small>A LIFE, ONE YEAR AT A TIME.</small></div><div class="art-stamp">人生<br>未完</div></div>
   </main>
   <section v-if="panel==='sources'" class="sources landing-sources"><h2>{{l('這是一個可玩的起點','A playable starting point')}}</h2><p>{{l('這版先驗證玩法與存檔。完整統計、法規與世界資料尚未匯入。','This version validates play and persistence. Full historical datasets and legal rules are not imported.')}}</p><article v-for="source in provenance" :key="source.id"><h3>{{text(source.title)}}</h3><p>{{text(source.text)}}</p><a v-if="source.url" :href="source.url" target="_blank" rel="noopener noreferrer">{{l('資料來源入口','Source portal')}} ↗</a></article></section>
   <p class="opening-notice">{{lang==='zh'?'遊玩前說明：本作使用真實臺灣地名、學校名錄與部分公開資料，名錄不足處使用生成校名；人物、日常劇情、薪資、費用、錄取與風險包含虛構或簡化設定，不代表真實個案、官方招生、就業機會或醫療與財務建議。詳細來源保留於資料說明。':'Before playing: real Taiwan places, schools and selected public data are combined with fictional or simplified people, stories, pay, costs, admissions and risks. This is not an actual admission, job offer or medical/financial recommendation. Sources remain in About.'}}</p><div class="landing-bottom"><span>01 / {{l('出生','BIRTH')}}</span><span>02 / {{l('成長與選擇','GROWTH & CHOICE')}}</span><span>03 / {{l('生活與傳承','LIFE & LEGACY')}}</span></div>
  </template>
  <template v-else-if="p">
   
   <div class="game-layout">
    <div class="character-column"><FamilyOverview :state="state" :lang="lang"/><aside class="character-panel"><div class="portrait" aria-hidden="true">{{p.name.slice(0,1)}}</div><p class="eyebrow">{{l('這一段人生','THIS LIFE')}}</p><h2>{{p.name}}</h2><p class="character-meta">{{ageText}} · {{location?text(location.name):''}}</p><p class="school-status" v-if="study">{{text(characterStatus(state,p))}}</p><a v-if="currentSchool" class="small-note" :href="currentSchool.source" target="_blank" rel="noopener noreferrer">{{l('學校資料來源','School source')}}</a><p v-if="p.life?.relationship?.active" class="relationship-status">{{l('交往對象：','Dating: ')}}{{state.people.find(n=>n.id===p!.life?.relationship?.personId)?.name}}</p><p class="identity-status">{{l('性別','Gender')}}：{{p.gender==='male'?l('男性','Male'):l('女性','Female')}} · {{l('喜歡','Attracted to')}}{{p.attractedTo==='male'?l('男生','men'):l('女生','women')}}</p><span class="generation">{{l('第','GENERATION ')}}{{state.generation}}{{l(' 代','')}}</span><div class="attribute-grid"><div v-for="(label,key) in attrs" :key="key"><span>{{text(label)}}</span><b>{{p.attributes[key]}}</b></div></div><div class="meters"><div v-for="item in [{key:'health',name:l('健康','Health')},{key:'fatigue',name:l('疲勞','Fatigue')},{key:'stress',name:l('壓力','Stress')},{key:'sanity',name:l('理智（遊戲值）','Sanity (game value)')}]" :key="item.key"><div><span>{{item.name}}</span><span>{{item.key==='sanity'?sanity(p):p[item.key as 'health'|'fatigue'|'stress']}} / 100</span></div><meter min="0" max="100" :value="item.key==='sanity'?sanity(p):p[item.key as 'health'|'fatigue'|'stress']" :aria-label="item.name"></meter><small v-if="item.key==='stress'||item.key==='fatigue'">{{l('近期來源：','Recent causes: ')}}{{wellbeingReasons(p,item.key as 'stress'|'fatigue').map(v=>text(v)).join('、')}}</small></div></div><p v-if="p.life?.clubNames?.length">{{p.life.clubNames.join('、')}}</p><p v-if="p.clubs?.length" class="small-note">{{l('參與社團：','Clubs: ')}}{{p.clubs.map(c=>({music:l('音樂社','Music'),sports:l('運動社','Sports'),film:l('電影社','Film'),volunteer:l('志工社','Volunteer')})[c]).join('、')}}</p><h3 class="side-heading">{{l('特殊專長與學科','SKILLS & PROFICIENCIES')}}</h3><div class="skill-grid"><div class="skill-row" v-for="(label,key) in skills" v-show="key!=='coffee'||p.skills.coffee>0" :key="key"><span>{{text(label)}}</span><b>{{p.skills[key]}}</b></div></div><p v-if="p.sport" class="small-note">{{l('體育主項：','Sport: ')}}{{sports.find(i=>i[0]===p?.sport)?.[lang==='zh'?1:2]}}</p><p v-if="p.musicTraining" class="small-note">{{l('音樂主修：','Music major: ')}}{{instruments.find(i=>i[0]===p?.musicTraining?.major)?.[lang==='zh'?1:2]}}</p><div v-if="(['junior','senior','vocational'].includes(study?.enrollment?.level??'')||study?.enrollment?.level==='primary'&&years>=10)" class="junior-subjects"><h3>{{l('學科熟練度','Subject proficiency')}}</h3><div v-for="(label,key) in juniorSubjects" :key="key" class="skill-row"><span>{{text(label)}}</span><b>{{subjectProficiency(p)[key]}}</b></div></div><p v-if="cancerLabel(p)">{{text(cancerLabel(p)!)}}</p><StudentRecords :person="p" :lang="lang" :state="state"/><div class="side-finance"><span>{{l('個人現金','Personal cash')}}</span><b>NT$ {{p.cash.toLocaleString()}}</b><small>{{l('稅前職位','Gross-pay role')}} · {{text(jobs[p.job])}}</small></div><button class="family-button" @click="panel=panel==='family'?'story':'family'">{{l('查看家人與物品','Family & possessions')}} →</button></aside></div>
    <div class="main-column">
     <div class="yearbar"><div><span class="year">{{state.year}}</span><span>{{l('年','')}} / {{phaseLabel}}</span></div><div class="save-indicator"><i></i>{{saveStatus}}</div></div>
     <nav class="page-tabs" :aria-label="l('遊戲頁面','Game pages')"><button v-for="tab in [{id:'story',name:l('人生故事','Story')},{id:'finance',name:l('財務帳本','Finances')},{id:'timeline',name:l('人生年表','Timeline')},{id:'items',name:l('物品欄','Belongings')}]" :key="tab.id" :class="{active:panel===tab.id}" @click="panel=tab.id">{{tab.name}}</button><div class="save-tools"><button class="text-button" @click="exportSave">{{l('匯出','Export')}}</button><label>{{l('匯入','Import')}}<input type="file" accept="application/json,.json" @change="importSave"></label><button class="text-button" @click="setup=true">{{l('新人生','New life')}}</button></div></nav>
     <section v-if="panel==='story'" class="story-view">
      <div class="scene-banner" :class="{'night':state.phase==='dead'}"><div class="scene-lines" aria-hidden="true"></div><span>{{state.phase==='dead'?l('故事暫歇，記憶留下。','A story ends. Memories remain.'):years>=30?l('轉眼又是一年，生活在不知不覺中累積。','Another year passes; life gathers momentum.'):l('日子慢慢過，故事慢慢長。','A life, one year at a time.')}}</span><small>{{l('台灣 · 人生記事','TAIWAN · A LIFE JOURNAL')}}</small></div>
      <article class="story-card"><div class="story-meta"><span>{{state.date.replaceAll('-',' / ')}}</span><span class="badge">{{phaseLabel}}</span></div>
       <template v-if="state.phase==='focus'"><p class="chapter-number">{{l('新的一年','A NEW YEAR')}}</p><h1>{{years>=30?l('接下來 '+(nextPlanningYear(state)-state.year)+' 年，你想把重心放在哪裡？','What will you focus on for the next '+(nextPlanningYear(state)-state.year)+' years?'):l('今年，你想把重心放在哪裡？','What will you focus on this year?')}}</h1><p class="narrative">{{l('你翻開新的一頁。不是每件事都能預料，但你可以替這一年寫下一個方向。','You turn a new page. You cannot predict everything, but you can give this year a direction.')}}</p><div v-if="years>=6" class="specialty-picker"><span>{{l('特殊專長方向','Specialty focus')}}</span><button :aria-pressed="p.specialty==='music'" @click="update(s=>setSpecialty(s,'music'))">{{l('音樂','Music')}}</button><button :aria-pressed="p.specialty==='sports'" @click="update(s=>setSpecialty(s,'sports'))">{{l('體育','Sports')}}</button></div><SportMajor v-if="p.specialty==='sports'&&years>=6&&(years<18||study?.active)" :person="p" :lang="lang" @select="sport=>update(s=>setSport(s,sport))"/><MusicMajor v-if="p.specialty==='music'&&years>=6&&(years<18||study?.active)" :person="p" :lang="lang" :year="state.year" @select="major=>update(s=>setMusicMajor(s,major))"/><div v-if="(['junior','senior','vocational'].includes(study?.enrollment?.level??'')||study?.enrollment?.level==='primary'&&years>=10)" class="music-major"><label for="junior-focus">{{l('讀書重點','Study focus')}}</label><select id="junior-focus" :value="p.juniorFocus??'all'" @change="update(s=>setJuniorFocus(s,($event.target as HTMLSelectElement).value as JuniorSubject|'all'))"><option value="all">{{l('五科平均準備','Prepare all five subjects')}}</option><option v-for="(label,key) in juniorSubjects" :key="key" :value="key">{{text(label)}}</option></select></div><div class="choices focus-choices"><button v-for="o in focuses(state)" :key="o.id" @click="choose(o.id)"><span>{{text(o.title)}} <i>↗</i></span><small>{{text(o.detail)}}</small></button></div><form class="free-action" @submit.prevent="freeAction"><label for="action">{{l('用自己的話寫下目標','Write a supported resolution')}}</label><div><input id="action" v-model="command" maxlength="80" :placeholder="l('例如：讀書、音樂、健康','Try: study, music, health')"><button type="submit">{{l('送出','Submit')}}</button></div></form></template>
       <NamingPanel v-else-if="state.phase==='naming'" :state="state" :lang="lang" :error="namingError" @confirm="confirmChildName"/>
       <template v-else-if="state.phase==='review'"><p class="chapter-number">YEAR IN REVIEW</p><h1>{{period&&period.years>1?l(`${period.from}–${period.to}，也成為了故事。`,`${period.from}–${period.to} becomes a story.`):l('這一年，也成為了故事。','Another year becomes a story.')}}</h1><div class="fortune-slip"><span>{{fortune}}</span><p>{{report?text(report.summary):l('你接下了家人的人生；世界和記憶都還在。','You take over an existing life. The world and its memories remain.')}}</p></div><p class="narrative">{{l('金錢與財產的變化已記錄於財務帳本。','Your financial changes are recorded in the ledger.')}}</p><div class="story-controls"><button class="primary" @click="move">{{l('迎接下一段人生','Begin the next chapter')}} →</button><button @click="panel='finance'">{{l('查看年度帳目','View annual accounts')}}</button></div></template>
       <template v-else-if="state.phase==='dead'"><Belongings :state="state" :lang="lang" memorial-only/><p class="chapter-number">{{l('人生終章','LIFE SUMMARY')}}</p><h1>{{l('人生的最後一頁','The final page')}}</h1><p class="narrative">{{l(`${p.name}的生命停在${ageText}，原因是${p.deathCause?text(p.deathCause):'疾病或意外'}。這段人生與家人的記憶已保存。`,`${p.name}'s life ended at ${ageText}, through ${p.deathCause?text(p.deathCause):'illness or accident'}. Their story and family memories are preserved.`)}}</p><p class="small-note">{{l('記錄日期：','Recorded date: ')}}{{p.deathDate}}</p><p class="narrative">{{l(`累積 ${p.history.length} 則人生紀錄，留下 ${p.children.length} 位子女。遺產暫列待處理，不會全數轉給所選後代。`,`${p.history.length} life records and ${p.children.length} children. The estate is held pending settlement, not automatically given to the chosen successor.`)}}</p><div v-if="successors(state).length" class="choices"><button v-for="n in successors(state)" :key="n.id" @click="update(s=>continueAs(s,n.id))"><span>{{l('繼續扮演','Continue as')}} {{n.name}}</span><small>{{age(state,n)}} {{l('歲 · 接手現有生活','years old · Keep their existing life')}}</small></button></div><p v-else class="small-note">{{l('沒有合資格的在世後代，這段人生到此結束。','There are no eligible living descendants. This run has ended.')}}</p><div class="story-controls"><button @click="panel='timeline'">{{l('回顧人生','Review this life')}}</button><button class="primary" @click="setup=true">{{l('開始新人生','Start a new life')}}</button></div></template>
       <template v-else><p class="chapter-number">{{state.current?.kind==='specialized'?(p.specialty==='sports'?l('特殊升學 · 體育術科','SPECIALIZED ADMISSION · SPORTS'):l('特殊升學 · 音樂術科','SPECIALIZED ADMISSION · MUSIC')):l('生活中的一頁','A PAGE OF LIFE')}}</p><h1>{{state.current?text(state.current.title):l('生活繼續往前','Life moves forward')}}</h1><p class="narrative">{{state.current?.kind==='enrollment'&&state.current.data==='senior'?l('以五科等級記錄升學結果，再選擇高中、高職或五專；音樂、體育入學使用相應術科檢定。','Five subject grades determine your next route; music and sports use specialty assessments.'):state.current?text(state.current.text):''}}</p><SportMajor v-if="state.phase==='event'&&['enrollment','universityentry'].includes(state.current?.kind??'')" :person="p" :lang="lang" @select="sport=>update(s=>setSport(s,sport))"/><MusicMajor v-if="state.phase==='event'&&['musicpractice','enrollment','universityentry'].includes(state.current?.kind??'')" :person="p" :lang="lang" :year="state.year" @select="major=>update(s=>setMusicMajor(s,major))"/>
        <div v-if="state.phase==='event'" class="choices"><button v-for="o in options(state)" :key="o.id" :disabled="o.disabled||busy" @click="choose(o.id)"><span>{{text(o.title)}} <i>↗</i></span><small>{{text(o.detail)}}</small></button></div>
        <div v-if="state.resolution" class="outcome" aria-live="polite"><div v-if="state.resolution.check" class="dice-check"><div class="die" :class="{rolling:busy}">{{busy?'…':state.resolution.check.die}}</div><div><span class="eyebrow">D20 · {{l('技能檢定','SKILL CHECK')}}</span><p v-if="!busy">{{state.resolution.check.die}} {{state.resolution.check.modifier>=0?'+':''}}{{state.resolution.check.modifier}} = <b>{{state.resolution.check.total}}</b> / {{l('難度','DC')}} {{state.resolution.check.dc}}<strong>{{state.resolution.check.success?l('通過','Passed'):l('未通過','Not passed')}}</strong></p><p v-else>{{l('骰子落下之前，深呼吸。','Take a breath as the die settles.')}}</p></div></div><div v-if="state.resolution.checks" class="subject-results"><div v-for="c in state.resolution.checks" :key="c.text.en" class="skill-row"><span>{{text(c.text)}}</span><b>{{busy?'…':capDisplay?capBand(c.total):`${c.die} + ${c.modifier} = ${c.total}`}}</b></div><p v-if="capDisplay">{{l('會考等級','CAP grades')}}：{{busy?'…':capResult(state.resolution.checks)}}</p><p v-else>{{l('五科總分','Five-subject total')}}：{{busy?'…':state.resolution.admissionTotal}}</p></div><p v-if="!busy">{{capDisplay?l('會考等級已記錄，接著選擇高中、高職或五專。','CAP grades retained; choose your education route.'):text(state.resolution.text)}}</p></div>
        <div v-if="state.phase!=='event'" class="story-controls"><button class="primary" :disabled="busy" @click="move">{{l('繼續故事','Continue the story')}} →</button><button :disabled="busy" @click="skipNarration">{{l('推進至下一個決定或年末','Advance to a decision / year end')}}</button></div>
       </template>
      </article>
      <section class="journal-card"><div class="section-title"><h2>{{l('本年記事','This year’s journal')}}</h2><span>{{l('生活裡的小事，都有回聲。','Small moments leave echoes.')}}</span></div><div id="year-journal" class="journal-scroll" tabindex="0" :aria-label="l('本年記事，可上下捲動','Year journal, scrollable')"><p v-if="!journal.length" class="empty">{{l('新的一頁，正等著寫下。','A new page waits to be written.')}}</p><div v-for="j in journal" :key="j.id" class="journal-entry"><time>{{j.date.slice(5).replace('-',' / ')}}</time><div><b>{{text(j.title)}}</b><p>{{text(j.text)}}</p></div></div></div></section>
     </section>
     <section v-else-if="panel==='finance'" class="detail-page"><p class="eyebrow">ANNUAL ACCOUNTS</p><h1>{{l('日子，也記在帳上。','Life, in the ledger.')}}</h1><p class="muted">{{l('金額為新臺幣；家庭資助、打工收入、伙食與學費分別記錄。','Amounts in NTD; family support, wages, meals and tuition are recorded separately.')}}</p><div class="money-grid"><div><span>{{l('個人現金','Personal cash')}}</span><b>{{p.cash.toLocaleString()}}</b></div><div><span>{{l('待償債務','Debt')}}</span><b>{{p.debt.toLocaleString()}}</b></div><div><span>{{l('勞退模擬專戶','Illustrative pension account')}}</span><b>{{p.pensionBalance.toLocaleString()}}</b></div></div><div v-if="report" class="account-summary"><h2>{{report.year}} {{l('年度結算','year-end closing')}}</h2><dl><div v-for="row in [{name:l('期初現金','Opening cash'),v:report.openingCash},{name:l('收入與家庭資助','Income and family support'),v:report.income},{name:l('已付支出與稅費','Paid expenses / deductions'),v:-report.expense},{name:l('新增貸款與待償債務','New loans and debt'),v:report.newDebt},{name:l('期末現金','Closing cash'),v:report.closingCash},{name:l('本年所得稅估列，明年支付','Accrued estimated tax, paid next year'),v:report.taxAccrued}]" :key="row.name"><dt>{{row.name}}</dt><dd>NT$ {{row.v.toLocaleString()}}</dd></div></dl></div><div v-if="period && period.years>1" class="account-summary"><h2>{{period.from}}–{{period.to}} · {{period.years}} {{l('年合計','years total')}}</h2><p>{{l('收入與資助','Income and support')}} NT$ {{period.income.toLocaleString()}} · {{l('支出','Expenses')}} NT$ {{period.expense.toLocaleString()}}</p><p>{{l('各年薪資、稅費與死亡風險仍逐年處理。','Income, taxes and mortality are processed each year.')}}</p></div><FinanceSummary :state="state" :lang="lang"/><div class="family-aid-total"><h2>{{l('本年家庭資助','Family support this year')}}</h2><b>NT$ {{state.ledger.filter(e=>e.personId===p!.id&&e.category==='familyAid'&&e.amount>0&&inPeriod(e.date)).reduce((v,e)=>v+e.amount,0).toLocaleString()}}</b><p>{{l('涵蓋家人實際支付的生活、學習與照顧費用。','Includes actual family contributions to living, education and care.')}}</p><p v-if="p.life?.unfundedNeeds">{{l('尚待安排的生活與學習支出：','Living and study needs awaiting support: ')}} NT$ {{p.life.unfundedNeeds.toLocaleString()}}</p><p v-if="p.life?.loanPrincipal">{{l('其中就學貸款本金：','Student loan principal: ')}} NT$ {{p.life.loanPrincipal.toLocaleString()}}</p></div><h2>{{l('本年流水帳','This year’s transactions')}}</h2><div class="ledger-list"><div v-for="entry in state.ledger.filter(e=>inPeriod(e.date)&&e.personId===p!.id).slice().reverse()" :key="entry.id"><time>{{entry.date.slice(5)}}</time><span>{{text(entry.text)}}</span><b :class="{negative:entry.amount<0}">{{entry.amount>0?'+':''}}{{entry.amount.toLocaleString()}}</b></div><p v-if="!state.ledger.some(e=>e.personId===p!.id)" class="muted">{{l('尚無個人交易，幼年生活由家庭支援。','No personal transactions yet. Your household supports early life.')}}</p></div></section>
     <section v-else-if="panel==='items'" class="detail-page"><Belongings :state="state" :lang="lang" @discard="id=>update(s=>discardItem(s,id))"/></section><section v-else-if="panel==='timeline'" class="detail-page"><HistoryRecords :state="state" :lang="lang"/><p class="eyebrow">LIFE TIMELINE</p><h1>{{l('你走過的那些日子','The days you have lived')}}</h1><div class="timeline"><div v-for="(h,i) in p.history.slice().reverse()" :key="i"><time>{{h.year}}</time><p>{{text(h.text)}}</p></div></div></section>
     <section v-else-if="panel==='family'" class="detail-page"><p class="eyebrow">PEOPLE & MEMORIES</p><h1>{{l('與你一起生活的人','The people in your life')}}</h1><article v-for="n in state.people.filter(n=>n.id!==p!.id)" :key="n.id" class="person-row"><span class="mini-portrait">{{n.name[0]}}</span><div><h3>{{n.name}} <small>{{n.alive?l(`${age(state,n)} 歲`,`${age(state,n)} years old`):l('已故','Deceased')}}</small></h3><p>{{text(jobs[n.job])}} · {{p.partnerId===n.id?l('伴侶／妻子','Partner / wife'):p.parentIds.includes(n.id)?l('生物／法律父母','Biological / legal parent'):p.children.includes(n.id)?l('子女','Child'):l('家族成員','Family member')}}</p><small>{{l('生活紀錄','Life records')}} {{n.history.length}} · {{l('現金','Cash')}} NT$ {{n.cash.toLocaleString()}}</small></div></article><h2>{{l('隨身物品與資格','Possessions & credentials')}}</h2><p class="muted">{{p.inventory.map(i=>({ 'birth-record':l('出生紀錄','Birth record'),scooter:l('機車','Scooter'),'used-car':l('二手汽車','Used car'),'camp-kit':l('露營與登山裝備','Camping and hiking gear'),ps5:'PS5',switch:'Nintendo Switch'} as Record<string,string>)[i]??i).join(' · ')||l('尚無物品','No possessions yet')}}</p><p>{{p.credentials.map(c=>c==='master-degree'?l('碩士學位（模擬）','Master’s degree (simulated)'):c==='music-admission'?l('音樂升學機會（模擬）','Music admission opportunity (pilot)'):c==='sports-admission'?l('體育升學機會（模擬）','Sports admission opportunity (pilot)'):c==='academic-admission'?l('一般升學機會（模擬）','Academic admission opportunity (pilot)'):l('中學升學評量通過（模擬）','Secondary assessment passed (pilot)')).join(' · ')}}</p></section>
     <section v-else class="detail-page sources"><p class="eyebrow">ABOUT THIS BUILD</p><h1>{{l('一個可玩的起點','A playable starting point')}}</h1><p>{{l('已離線匯入教育部 115 學年度（2026–2027）國小 2,609 筆、國中 740 筆，涵蓋 367 個有資料的行政區；遊戲過程不向外查詢學校。','Bundled MOE academic-year 115 (2026–2027) directory: 2,609 primary and 740 junior-high records in 367 listed districts. Gameplay makes no school lookup requests.')}}</p><article v-for="source in provenance" :key="source.id"><h3>{{text(source.title)}}</h3><p>{{text(source.text)}}</p><a v-if="source.url" :href="source.url" target="_blank" rel="noopener noreferrer">{{l('官方來源入口','Official source portal')}} ↗</a></article><p><a href="./uniform-library.html" target="_blank" rel="noopener noreferrer">{{l('學校字典與夏季制服圖庫','School directory and summer uniform library')}} ↗</a></p><CareerSources :lang="lang"/><h2>{{l('已實作','Implemented')}}</h2><p>{{l('種子重現、不同自主起點、嬰幼兒自動敘事與早逝、年度目標、事件選擇、D20、學科／術科、工作與失業、專長成長、簡化家庭與帳目、後代接手、存檔匯入匯出。','Seeded replay, variable agency onset, automatic infancy and early death, annual goals, interactive events, D20, academic/specialized routes, jobs and layoffs, adult skills, simplified family and accounts, descendant continuation, local save/import/export.')}}</p><h2>{{l('仍待擴充','Still planned')}}</h2><p>{{l('完整2026人口校準、分齡健康與疫苗、學校與完整招生、農曆節慶、兵役、伴侶與監護細節、完整托育、法定稅保與退休、完整房車與企業法規、投資、遺產分配與 Flutter。','Complete 2026 population calibration, age-specific health/vaccines, schools/admissions, lunar holidays, military service, partners/guardianship, full childcare, statutory finance/retirement, complete property/business rules, investment, estate distribution and Flutter.')}}</p><p class="small-note">{{l('自主決策年齡為 2–4 歲的遊戲估值，非醫學判定。未來版本更動規則或資料時會新增存檔遷移；目前使用 schema 7 / slice-7，並自動升級 v1／v2／v3／v4／v5／v6 存檔。','Agency at age 2–4 is a game assumption, not a medical claim. Rule/data changes require save migration; v1/v2/v3/v4/v5/v6 saves migrate to schema 7 / slice-7.')}}</p></section>
    </div>
   </div>
  </template>
  <footer class="app-footer"><span>新年新希望 / New Year Resolution</span><span>{{l('一段人生，很多種可能。','One life. Many possibilities.')}}</span></footer>
  <div v-if="setup" class="dialog-backdrop" @click.self="setup=false"><section class="setup-dialog" role="dialog" aria-modal="true" aria-labelledby="setup-title" @keydown="trapFocus"><button class="close-dialog" @click="setup=false" :aria-label="l('關閉','Close')">×</button><p class="eyebrow">A NEW BEGINNING</p><h2 id="setup-title">{{l('你的故事，從哪一年開始？','When does your story begin?')}}</h2><form @submit.prevent="start"><p class="opening-notice">{{lang==='zh'?'開始前：本作以真實名錄搭配虛構故事，薪資、費用、風險及招生是簡化的遊戲設定；名錄不足處使用生成校名，來源可在資料說明查看。':'Before starting: real directories are combined with fictional stories and simplified pay, costs, risks and admissions. Missing school names are generated; sources are in About.'}}</p><label for="birth-year">{{l('出生年份','Birth year')}}</label><input id="birth-year" v-model.number="birth" type="number" min="1980" max="2026" required autofocus><details><summary>{{l('進階：人生種子','Advanced: life seed')}}</summary><label for="seed">{{l('人生種子','Life seed')}}</label><input id="seed" v-model="seed" maxlength="100" required></details><p class="small-note">{{l('相同種子、出生年與選擇會重現相同結果。出生地依2025人口快照抽樣，家庭數值為遊戲設定。','The same seed, birth year and choices reproduce the same life. Origins use the 2025 population snapshot; family values are game settings.')}}</p><p v-if="saved||state" class="replace-warning">{{l('開始後會覆寫本機自動存檔；請先匯出想保留的人生。','Starting replaces your local autosave. Export any life you want to keep first.')}}</p><button type="button" v-if="state" @click="exportSave">{{l('先匯出目前人生','Export current life first')}}</button><button type="submit" class="primary">{{l('開始人生','Begin life')}} →</button></form></section></div>
 </div>
</template>
